#include "JointOrigin.h"
#include <BRepAdaptor_Curve.hxx>
#include <BRepAdaptor_Surface.hxx>
#include <TopExp.hxx>
#include <TopExp_Explorer.hxx>
#include <TopTools_IndexedMapOfShape.hxx>
#include <TopoDS.hxx>
#include <QUuid>
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace {
void require(bool v,const char* message){if(!v)throw std::invalid_argument(message);}
gp_Dir directed(const gp_Dir& d){if(std::abs(d.Y())>1-1e-8)return gp_Dir(0,1,0);if(std::abs(d.Z())>1-1e-8)return gp_Dir(0,0,1);throw std::invalid_argument("Joint inference supports the fixture's Y/Z cylinder axes");}
const EvaluatedSolidEdge& edge(const EvaluatedBody& b,const QString& id){const EvaluatedSolidEdge* found=nullptr;for(const auto& e:b.solidEdges)if(e.edgeId==id){require(!found,"Retained origin edge identity is ambiguous");found=&e;}require(found&&!found->edge.IsNull(),"Retained origin rim is deleted or unavailable");return *found;}
JointOrigin::Resolved circle(const TopoDS_Edge& e){BRepAdaptor_Curve c(e);require(c.GetType()==GeomAbs_Circle&&std::abs(std::abs(c.LastParameter()-c.FirstParameter())-2*std::acos(-1.0))<1e-6,"Joint inference needs a complete circular rim");const auto value=c.Circle();require(std::isfinite(value.Radius())&&value.Radius()>1e-6,"Circular origin radius is invalid");return {value.Location(),directed(value.Axis().Direction()),value.Radius(),{}};}
bool contains(const TopoDS_Face& f,const TopoDS_Edge& e){TopTools_IndexedMapOfShape edges;TopExp::MapShapes(f,TopAbs_EDGE,edges);return edges.Contains(e);}
bool compatible(const TopoDS_Face& face,const JointOrigin::Resolved& a,const JointOrigin::Resolved& b){BRepAdaptor_Surface s(face);if(s.GetType()!=GeomAbs_Cylinder)return false;const double uSpan=s.LastUParameter()-s.FirstUParameter(),vSpan=s.LastVParameter()-s.FirstVParameter();if(!std::isfinite(uSpan)||!std::isfinite(vSpan)||std::abs(uSpan-2*std::acos(-1.0))>1e-6||vSpan<1e-6)return false;const auto cylinder=s.Cylinder();if(std::abs(cylinder.Radius()-a.radiusMm)>1e-6||std::abs(a.radiusMm-b.radiusMm)>1e-6||a.axis.Dot(b.axis)<1-1e-8)return false;const gp_Vec delta(a.center,b.center);if(delta.Crossed(gp_Vec(a.axis)).Magnitude()>1e-6||std::abs(delta.Dot(gp_Vec(a.axis)))<1e-6||std::abs(vSpan-std::abs(delta.Dot(gp_Vec(a.axis))))>1e-6)return false;return std::abs(cylinder.Axis().Direction().Dot(a.axis))>1-1e-8&&gp_Vec(cylinder.Location(),a.center).Crossed(gp_Vec(a.axis)).Magnitude()<1e-6;}
QJsonObject descriptor(const EvaluatedBody& b,QJsonObject position,const JointOrigin::Resolved& r){if(!b.occurrenceId.isEmpty())position["occurrenceId"]=b.occurrenceId;const bool midpoint=position.contains("rimEdgeIds");QString faceKey;if(midpoint){const auto ids=position["rimEdgeIds"].toArray();faceKey=QUuid::createUuidV5(QUuid(b.bodyId),"joint-cylinder-face/1\n"+ids[0].toString().toUtf8()+'\n'+ids[1].toString().toUtf8()).toString(QUuid::WithoutBraces);}return {{"position",position},{"centerMm",QJsonArray{r.center.X(),r.center.Y(),r.center.Z()}},{"axis",QJsonArray{r.axis.X(),r.axis.Y(),r.axis.Z()}},{"radiusMm",r.radiusMm},{"snapKind",midpoint?"cylinderAxisMidpoint":"circleCenter"},{"faceKey",faceKey}};}
}
QString JointOrigin::validateReference(const QJsonObject& p){if(QUuid(p["bodyId"].toString()).isNull())return "Joint origin requires a source body UUID";if(p.contains("edgeId")){if(p.size()!=2||p["edgeId"].toString().isEmpty())return "Circle center requires only bodyId and retained edgeId";return {};}const auto ids=p["rimEdgeIds"].toArray();if(p.size()!=3||p["snapKind"]!="cylinderAxisMidpoint"||ids.size()!=2||!ids[0].isString()||!ids[1].isString()||ids[0].toString().isEmpty()||ids[1].toString().isEmpty()||ids[0]==ids[1])return "Cylinder midpoint requires two distinct retained rim IDs and its snap kind";return {};}
JointOrigin::Resolved JointOrigin::resolve(const EvaluatedBody& b,const QJsonObject& p){const auto error=validateReference(p);require(error.isEmpty(),qPrintable(error));require(p["bodyId"]==b.bodyId,"Origin reference body does not match");if(p.contains("edgeId"))return circle(edge(b,p["edgeId"].toString()).edge);const auto ids=p["rimEdgeIds"].toArray();const auto& first=edge(b,ids[0].toString());const auto& last=edge(b,ids[1].toString());const auto a=circle(first.edge),z=circle(last.edge);TopoDS_Face result;int count=0;for(TopExp_Explorer f(b.shape,TopAbs_FACE);f.More();f.Next()){const auto face=TopoDS::Face(f.Current());if(contains(face,first.edge)&&contains(face,last.edge)&&compatible(face,a,z)){result=face;++count;}}require(count==1,"Retained rim pair does not resolve one unique current finite cylinder face");return {gp_Pnt((a.center.X()+z.center.X())/2,(a.center.Y()+z.center.Y())/2,(a.center.Z()+z.center.Z())/2),a.axis,a.radiusMm,result};}
QJsonObject JointOrigin::circleCandidate(const EvaluatedBody& b,const QString& id){QJsonObject p{{"bodyId",b.bodyId},{"edgeId",id}};return descriptor(b,p,resolve(b,p));}
QJsonObject JointOrigin::cylindricalFaceCandidate(const EvaluatedBody& b,const TopoDS_Face& f){require(!f.IsNull()&&BRepAdaptor_Surface(f).GetType()==GeomAbs_Cylinder,"Hover one finite cylindrical face");bool present=false;for(TopExp_Explorer face(b.shape,TopAbs_FACE);face.More();face.Next())present|=f.IsSame(face.Current());require(present,"Picked cylinder face is not in this exact instance body");TopTools_IndexedMapOfShape boundary;TopExp::MapShapes(f,TopAbs_EDGE,boundary);QStringList ids;int circular=0;for(int i=1;i<=boundary.Extent();++i){const auto actual=TopoDS::Edge(boundary(i));BRepAdaptor_Curve c(actual);if(c.GetType()!=GeomAbs_Circle)continue;circle(actual);++circular;QString id;for(const auto& retained:b.solidEdges)if(!retained.edge.IsNull()&&retained.edge.IsSame(actual)){require(id.isEmpty(),"Picked cylinder rim has ambiguous retained lineage");id=retained.edgeId;}require(!id.isEmpty(),"Picked cylinder face lacks complete retained rim lineage");ids.append(id);}require(circular==2&&ids.size()==2&&ids[0]!=ids[1],"Picked cylinder needs exactly two complete retained circular boundaries");ids.sort();QJsonObject p{{"bodyId",b.bodyId},{"rimEdgeIds",QJsonArray{ids[0],ids[1]}},{"snapKind","cylinderAxisMidpoint"}};const auto r=resolve(b,p);require(r.face.IsSame(f),"Retained cylinder pair does not identify the picked face");return descriptor(b,p,r);}
std::vector<QJsonObject> JointOrigin::cylindricalCandidates(const EvaluatedBody& b){std::vector<QJsonObject> result;for(TopExp_Explorer f(b.shape,TopAbs_FACE);f.More();f.Next())if(BRepAdaptor_Surface(TopoDS::Face(f.Current())).GetType()==GeomAbs_Cylinder)try{result.push_back(cylindricalFaceCandidate(b,TopoDS::Face(f.Current())));}catch(const std::exception&){}return result;}
